import { randomUUID } from 'node:crypto';

import type { Logger } from '@helmrun/logger';
import type { Request, RequestHandler } from 'express';
import * as z from 'zod';

export const REQUEST_ID_HEADER = 'x-request-id';
export const REQUEST_ID_MAX_LENGTH = 128;

// Validates a client-supplied ID before it's recorded: short and safe
// characters only, so a header can't inject newlines or JSON into the logs.
export const requestIdSchema = z
  .string()
  .min(1)
  .max(REQUEST_ID_MAX_LENGTH)
  .regex(/^[A-Za-z0-9._-]+$/u);

export interface RequestContext {
  // Always generated by the API, so it uniquely identifies one request and
  // can't be chosen or reused by a client (decision 011).
  readonly requestId: string;
  // The client's own x-request-id, if it sent a valid one. Recorded so a client
  // can quote it, but never used as the correlation key.
  readonly clientRequestId: string | undefined;
  // Child logger with both IDs bound, so every log line for this request
  // carries them without callers passing them around.
  readonly logger: Logger;
}

declare global {
  // Express exposes its Request type as an open global interface for app fields.
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      // Set by the request ID middleware. Optional in the type because anything
      // registered before that middleware runs without it; read it through
      // requireRequestContext().
      requestContext?: RequestContext;
    }
  }
}

// Fails loudly if middleware order is ever wrong, instead of a vague TypeError
// deep inside a handler.
export const requireRequestContext = (request: Request): RequestContext => {
  if (request.requestContext === undefined) {
    throw new Error('requestContext is missing: the request ID middleware must run first');
  }

  return request.requestContext;
};

export const createRequestIdMiddleware = (
  rootLogger: Logger,
  generateRequestId: () => string = randomUUID,
): RequestHandler => {
  return (request, response, next) => {
    const requestId = generateRequestId();
    const incoming = requestIdSchema.safeParse(request.get(REQUEST_ID_HEADER));
    const clientRequestId = incoming.success ? incoming.data : undefined;

    request.requestContext = {
      requestId,
      clientRequestId,
      logger: rootLogger.child(
        clientRequestId === undefined ? { requestId } : { requestId, clientRequestId },
      ),
    };
    // Our ID, echoed back so a client (or support ticket) can quote it.
    response.setHeader(REQUEST_ID_HEADER, requestId);

    next();
  };
};
